def get_history(asset, bar_count, frequency='1d', fields=None, fq=None, skip_suspended=False, include=False, fill='nan'):
    assets = assure_assets(asset)
    if not assets:
        if isinstance(asset, list):
            return {}
        else:
            return EMPTY_BAR_NP_ARRAY
    else:
        engine_obj = engine_instance()
        if frequency == '1d':
            sys_frequency = engine_obj.config.strategy.frequency
            if sys_frequency in ('1m', 'tick'):
                if include:
                    if ExecutionContext.phase() == const.ExecutionPhase.BEFORE_TRADING_START:
                        query_date = data_proxy().get_previous_trading_date(engine_obj.trading_dt.date())
                        include = False
                    else:
                        query_date = engine_instance().calendar_dt
        else:
            query_date = engine_instance().calendar_dt
        query_date = datetime_func.convert_dt_to_int(query_date)
        if isinstance(asset, list):
            if skip_suspended:
                raise exception.IQInvalidArgument('跳过停牌模式下，只支持单只合约的查询')
            return {one_asset.symbol: data_proxy().get_history(one_asset, bar_count, query_date, frequency, fields, fq, skip_suspended, include, fill) for one_asset in assets}
        else:
            return data_proxy().get_history(assets[0], bar_count, query_date, frequency, fields, fq, skip_suspended, include, fill)
