def get_price(asset, start_date, end_date=None, frequency='1d', fields=None, fq=None, skip_suspended=False):
    assets = assure_assets(asset)
    start_date = datetime_func.convert_dt_to_int(datetime_func.to_timestamp(start_date))
    if end_date is not None:
        end_date = datetime_func.convert_dt_to_int(datetime_func.to_timestamp(end_date))
    if isinstance(asset, list):
        if skip_suspended:
            raise exception.IQInvalidArgument('跳过停牌模式下，只支持单只合约的查询')
        return {one_asset.symbol: data_proxy().get_price(one_asset, start_date, end_date, frequency, fields, fq, skip_suspended) for one_asset in assets}
    else:
        return data_proxy().get_price(assets[0], start_date, end_date, frequency, fields, fq, skip_suspended)
