@ExecutionContext.enforce_phase(const.ExecutionPhase.BEFORE_TRADING_START, const.ExecutionPhase.ON_HANDLE_AUCTION, const.ExecutionPhase.ON_HANDLE_DATA, const.ExecutionPhase.AFTER_TRADING_END, const.ExecutionPhase.ON_HANDLE_TICK, const.ExecutionPhase.SCHEDULED, const.ExecutionPhase.GLOBAL, const.ExecutionPhase.ON_ORDER_RSP, const.ExecutionPhase.ON_TRADE_RSP, const.ExecutionPhase.ON_STRATEGY_SIGNAL_RSP)
@arg_checker.apply_rules(arg_checker.verify_arg('asset_or_symbol').is_valid_asset(), arg_checker.verify_arg('amount').is_number().compare(const.CompareEnum.GE, 0), arg_checker.verify_arg('entrust_direction').is_instance((six.string_types, EntrustDirection)), arg_checker.verify_arg('futures_direction').is_instance((six.string_types, FuturesDirection)), arg_checker.verify_arg('style').is_instance((MarketOrder, LimitOrder, GearOrder, None.__class__)), arg_checker.verify_arg('hedge_type').is_instance((six.string_types, const.HedgeType)))
def order(asset_or_symbol, amount, entrust_direction, style=MarketOrder(), futures_direction=FuturesDirection.OPEN, hedge_type=const.HedgeType.SPECULATION):
    """
    下单函数

    :return:
    :param asset_or_symbol:
    :param amount:
    :param entrust_direction:
    :param futures_direction:
    :param style:
    :param hedge_type: 对冲类型
    :return:
    """
    if isinstance(style, LimitOrder) and style.get_price() <= 0:
        strategy_log.error('限价价格异常：%s' % style.get_price())
        return None
    else:
        asset = assure_asset(asset_or_symbol)
        if asset.type == const.AssetType.INDEX.value:
            strategy_log.error('不支持委托指数：%s' % asset.symbol)
            return None
        elif amount < 0:
            strategy_log.error(_('标的{asset.symbol}委托数量异常:数量应当大于0'.format(asset=asset)))
            return None
        elif amount == 0:
            strategy_log.error(_('标的{asset.symbol}委托数量为0，取消下单'.format(asset=asset)))
            return None
        elif isinstance(entrust_direction, six.string_types):
            entrust_direction = EntrustDirection(entrust_direction.upper())
        if isinstance(futures_direction, six.string_types):
            futures_direction = FuturesDirection(futures_direction.upper())
        if isinstance(hedge_type, six.string_types):
            hedge_type = const.HedgeType(hedge_type.upper())
        submit_order = Order.create_order(asset, amount, entrust_direction, style, futures_direction, hedge_type=hedge_type)
        engine = engine_instance()
        if engine.can_submit_order(submit_order):
            engine.algo.submit_order(submit_order)
            return submit_order
