@arg_checker.apply_rules(arg_checker.verify_arg('symbol_or_asset').is_valid_asset())
def set_benchmark(symbol_or_asset):
    engine = Engine.instance()
    asset = engine.get_asset(symbol_or_asset)
    if asset:
        engine.config.strategy.benchmark = asset.symbol
        engine.benchmark_portfolio = engine.create_benchmark_portfolio()
        return None
    else:
        strategy_log.warning('无法获取到%s对应的数据，设置基准失败' % symbol_or_asset)
